// MineBench Competitive Build: The Iron Horse
// A massive, detailed steam locomotive with tender and passenger cars.

const BLOCK = {
  IRON: 'iron_block',
  GOLD: 'gold_block',
  GLASS: 'glass',
  STEAM: 'stone',
  STONE_BRICK: 'stone_bricks',
  COBBLE: 'cobblestone',
  WOOD_PLANK: 'oak_planks',
  WOOD_LOG: 'oak_log',
  WOOL_RED: 'red_wool',
  WOOL_BLUE: 'blue_wool',
  WOOL_GREEN: 'green_wool',
  WOOL_WHITE: 'white_wool',
  WOOL_BLACK: 'black_wool',
  WOOL_YELLOW: 'yellow_wool',
  WOOL_BROWN: 'brown_wool',
  COAL: 'gray_wool',
  DIRT: 'dirt',
  GRASS: 'grass_block'
};

// Helper: Set a block if within grid bounds
function place(x, y, z, type) {
  if (x >= 0 && x < 256 && y >= 0 && y < 256 && z >= 0 && z < 256) {
    block(x, y, z, type);
  }
}

// Helper: Draw a filled ellipse in the XZ plane at height Y
function drawEllipseXZ(cx, cy, cz, rx, rz, rType) {
  for (let x = cx - rx; x <= cx + rx; x++) {
    for (let z = cz - rz; z <= cz + rz; z++) {
      let dx = (x - cx) / rx;
      let dz = (z - cz) / rz;
      if (dx * dx + dz * dz <= 1.0) {
        place(x, cy, z, rType);
      }
    }
  }
}

// Helper: Draw a ring in the XZ plane (hollow ellipse)
function drawRingXZ(cx, cy, cz, rx, rz, rType) {
  for (let x = cx - rx; x <= cx + rx; x++) {
    for (let z = cz - rz; z <= cz + rz; z++) {
      let dx = (x - cx) / rx;
      let dz = (z - cz) / rz;
      let dist = dx * dx + dz * dz;
      if (dist <= 1.0 && dist >= 0.85) {
        place(x, cy, z, rType);
      }
    }
  }
}

// Helper: Draw a filled circle in XY plane at Z
function drawCircleXY(cx, cy, cz, r, rType) {
  for (let x = cx - Math.ceil(r); x <= cx + Math.ceil(r); x++) {
    for (let y = cy - Math.ceil(r); y <= cy + Math.ceil(r); y++) {
      let dx = (x - cx) / r;
      let dy = (y - cy) / r;
      if (dx * dx + dy * dy <= 1.0) {
        place(x, y, cz, rType);
      }
    }
  }
}

// Helper: Draw a ring in XY plane at Z
function drawRingXY(cx, cy, cz, r, rType) {
  for (let x = cx - Math.ceil(r); x <= cx + Math.ceil(r); x++) {
    for (let y = cy - Math.ceil(r); y <= cy + Math.ceil(r); y++) {
      let dx = (x - cx) / r;
      let dy = (y - cy) / r;
      let dist = dx * dx + dy * dy;
      if (dist <= 1.0 && dist >= 0.85) {
        place(x, y, cz, rType);
      }
    }
  }
}

// Helper: Draw a line between two points
function drawLine(x1, y1, z1, x2, y2, z2, type) {
  let dx = Math.abs(x2 - x1);
  let dy = Math.abs(y2 - y1);
  let dz = Math.abs(z2 - z1);
  let steps = Math.max(dx, Math.max(dy, dz));
  if (steps === 0) return;

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let x = Math.round(x1 + (x2 - x1) * t);
    let y = Math.round(y1 + (y2 - y1) * t);
    let z = Math.round(z1 + (z2 - z1) * t);
    place(x, y, z, type);
  }
}

// Helper: Draw a smooth curve using quadratic bezier approximation
function drawCurve(x0, y0, z0, x1, y1, z1, x2, y2, z2, steps, type) {
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let x = Math.round((1-t)*(1-t)*x0 + 2*(1-t)*t*x1 + t*t*x2);
    let y = Math.round((1-t)*(1-t)*y0 + 2*(1-t)*t*y1 + t*t*y2);
    let z = Math.round((1-t)*(1-t)*z0 + 2*(1-t)*t*z1 + t*t*z2);
    place(x, y, z, type);
  }
}

// --- BUILD FUNCTIONS ---

function buildTrack(baseZ) {
  // Rails and sleepers
  let trackWidth = 4;
  let trackLength = 800;

  for (let z = baseZ; z < baseZ + trackLength; z++) {
    // Sleepers (ties)
    if ((z - baseZ) % 3 === 0) {
      box(120, 4, z, 136, 5, z, BLOCK.WOOD_LOG);
    }

    // Rails
    let railY = 6;
    place(122, railY, z, BLOCK.IRON);
    place(134, railY, z, BLOCK.IRON);

    // Ballast (gravel/stone bed)
    box(118, 3, z - 1, 138, 3, z + 1, BLOCK.STONE);
    box(119, 4, z - 1, 137, 5, z + 1, BLOCK.COBBLE);
  }
}

function buildTender(xStart) {
  let x = xStart;
  let y = 6;
  let z = 0; // Local Z for tender

  // Main body: Coal bunker
  box(x, y + 2, z, x + 14, y + 8, z + 16, BLOCK.WOOL_BROWN);

  // Roof
  for (let dx = 0; dx <= 14; dx++) {
    for (let dz = 0; dz <= 16; dz++) {
      let h = Math.floor(Math.sin((dx / 14) * Math.PI) * 2);
      place(x + dx, y + 8 + h, z + dz, BLOCK.WOOL_BLACK);
    }
  }

  // Coal pile (inside)
  box(x + 1, y + 3, z + 1, x + 13, y + 7, z + 15, BLOCK.COAL);

  // Water tanks on sides
  for (let dz = 0; dz <= 16; dz++) {
    let w = Math.floor(Math.sin((dz / 16) * Math.PI) * 3);
    box(x - 2, y + 2, z + dz, x - 2, y + 7, z + dz, BLOCK.IRON);
    box(x + 16, y + 2, z + dz, x + 16, y + 7, z + dz, BLOCK.IRON);
  }

  // Buffer beam
  box(x, y + 3, z - 1, x + 14, y + 5, z - 1, BLOCK.WOOL_BLACK);
  place(x + 2, y + 4, z - 2, BLOCK.IRON);
  place(x + 12, y + 4, z - 2, BLOCK.IRON);
}

function buildEngine(xStart) {
  let x = xStart;
  let y = 6; // Wheel base level
  let z = 0; // Local Z

  // --- WHEELS ---
  // 3 sets of driving wheels: Front, Middle, Rear
  let wheelPositions = [8, 14, 20]; // Relative to engine front x
  let wheelRadius = 4;

  for (let wx of wheelPositions) {
    let cx = x + wx;
    let cy = y + wheelRadius;

    // Left Wheel
    drawRingXY(cx, cy, z - 2, wheelRadius, BLOCK.IRON);
    place(cx, cy, z - 2, BLOCK.GOLD); // Hub

    // Right Wheel
    drawRingXY(cx, cy, z + 2, wheelRadius, BLOCK.IRON);
    place(cx, cy, z + 2, BLOCK.GOLD); // Hub

    // Axle connecting them
    line(cx, cy, z - 2, cx, cy, z + 2, BLOCK.STONE_BRICK);
  }

  // --- BOILER ---
  // Tapered cylinder. Length ~40 blocks. Radius decreases from back to front.
  let boilerLength = 36;
  let maxRadius = 7;
  let minRadius = 5;

  for (let i = 0; i <= boilerLength; i++) {
    let t = i / boilerLength;
    // Radius: wider at back (t=1), narrower at front (t=0)
    let r = minRadius + (maxRadius - minRadius) * Math.pow(t, 0.5); 

    let cx = x + i;
    let cy = y + maxRadius; // Center of boiler vertically

    // Draw slice
    for (let dx = -Math.ceil(r); dx <= Math.ceil(r); dx++) {
      for (let dz = -Math.ceil(r); dz <= Math.ceil(r); dz++) {
        if (dx*dx + dz*dz <= r*r) {
          place(cx, cy + dx, z + dz, BLOCK.STEAM);
        }
      }
    }
  }

  // --- SMOKEBOX (Front of boiler) ---
  let sbX = x;
  box(sbX - 2, y + 4, z - 5, sbX - 2, y + 10, z + 5, BLOCK.STEAM);
  drawCircleXY(sbX - 3, y + 7, z, 6, BLOCK.WOOL_BLACK); // Smokebox door

  // --- COWCATCHER (Pilot) ---
  for (let i = 0; i < 8; i++) {
    let width = 4 + i;
    let height = 2 - (i/4);
    place(sbX - 3 - i, y + 2, z - width, BLOCK.IRON);
    place(sbX - 3 - i, y + 2, z + width, BLOCK.IRON);
    drawLine(sbX - 3 - i, y + 2, z - width, sbX - 3 - i, y + 2, z + width, BLOCK.IRON);
  }

  // --- CHIMNEY (Smokestack) ---
  let chimneyX = x + 4;
  let chimneyY = y + 15;
  box(chimneyX - 2, chimneyY, z - 2, chimneyX + 2, chimneyY + 6, z + 2, BLOCK.IRON);
  // Top flare
  box(chimneyX - 3, chimneyY + 6, z - 3, chimneyX + 3, chimneyY + 8, z + 3, BLOCK.WOOL_BLACK);

  // --- DOME (Steam Dome) ---
  drawCircleXY(x + 20, y + maxRadius + 1, z, 4, BLOCK.GOLD);
  box(x + 17, y + maxRadius + 1, z - 1, x + 23, y + maxRadius + 1, z + 1, BLOCK.GOLD);

  // --- CAB (Rear) ---
  let cabX = x + boilerLength;
  box(cabX, y + 4, z - 6, cabX + 10, y + 12, z + 6, BLOCK.WOOD_PLANK);

  // Cab Roof (Curved)
  for (let dx = 0; dx <= 10; dx++) {
    for (let dz = -6; dz <= 6; dz++) {
      let h = Math.floor(Math.sin((dx / 10) * Math.PI) * 3);
      place(cabX + dx, y + 12 + h, z + dz, BLOCK.WOOL_BLACK);
    }
  }

  // Cab Windows
  box(cabX, y + 7, z - 6, cabX + 8, y + 9, z - 6, BLOCK.GLASS);
  box(cabX, y + 7, z + 6, cabX + 8, y + 9, z + 6, BLOCK.GLASS);

  // --- CONNECTING RODS ---
  // Connects wheels to piston (front)
  let rodY = y + 2;
  for (let wx of wheelPositions) {
    let cx = x + wx;
    drawLine(cx, rodY, z - 1, cx + 4, rodY, z - 1, BLOCK.IRON);
    drawLine(cx, rodY, z + 1, cx + 4, rodY, z + 1, BLOCK.IRON);
  }

  // Buffer beam at rear
  box(cabX + 10, y + 3, z - 6, cabX + 10, y + 5, z + 6, BLOCK.WOOL_BLACK);
}

function buildCar(xStart, color) {
  let x = xStart;
  let y = 6;
  let z = 0;

  // Body
  box(x, y + 2, z, x + 30, y + 8, z + 10, color);

  // Roof
  for (let dx = 0; dx <= 30; dx++) {
    for (let dz = 0; dz <= 10; dz++) {
      let h = Math.floor(Math.sin((dx / 30) * Math.PI) * 2);
      place(x + dx, y + 8 + h, z + dz, BLOCK.WOOL_BLACK);
    }
  }

  // Windows
  for (let i = 2; i < 28; i += 4) {
    box(x + i, y + 4, z - 1, x + i + 2, y + 6, z - 1, BLOCK.GLASS);
    box(x + i, y + 4, z + 1, x + i + 2, y + 6, z + 1, BLOCK.GLASS);
  }

  // Buffers
  place(x - 1, y + 4, z - 3, BLOCK.IRON);
  place(x - 1, y + 4, z + 3, BLOCK.IRON);
  place(x + 31, y + 4, z - 3, BLOCK.IRON);
  place(x + 31, y + 4, z + 3, BLOCK.IRON);
}

// --- MAIN EXECUTION ---

function main() {
  // 1. Build the Track
  buildTrack(0);

  // 2. Build the Landscape (Simple base)
  box(110, 0, -50, 146, 2, 900, BLOCK.GRASS);
  box(110, 3, -50, 146, 3, 900, BLOCK.DIRT);

  // 3. Build the Train Components
  // Engine is at Z=0, facing +Z
  buildEngine(120); // X center ~128

  // Tender connects to rear of engine (Engine ends approx at Z=36)
  buildTender(120);

  // Passenger Cars
  // Car 1 starts after tender (Tender length ~16)
  buildCar(120, BLOCK.WOOL_RED);

  // Car 2
  buildCar(155, BLOCK.WOOL_BLUE);

  // Car 3
  buildCar(190, BLOCK.WOOL_GREEN);

  // 4. Add Smoke Particles (Using Gray Wool)
  let engineZ = 2; // Chimney Z
  let chimneyX = 124;
  let chimneyY = 27;

  for (let i = 0; i < 50; i++) {
    let px = chimneyX + Math.floor((Math.random() - 0.5) * 6);
    let py = chimneyY + Math.floor(Math.random() * 15);
    let pz = engineZ + Math.floor((Math.random() - 0.5) * 4);
    place(px, py, pz, BLOCK.WOOL_BLACK);
  }
}

main();
